TOOLS.rims = {
  html: function(p){
    return ''+
    '<label class="f-lbl">What is on the car now?</label>'+
    '<div class="chips" id="'+p+'-wh" data-single="1">'+
      '<button type="button" class="chip" data-v="alloy">Factory alloy wheels<small>The shiny ones it came with</small></button>'+
      '<button type="button" class="chip" data-v="steel">Steel wheels with plastic covers</button>'+
      '<button type="button" class="chip" data-v="after">Aftermarket alloys<small>Bought separately</small></button>'+
      '<button type="button" class="chip" data-v="have">I already own a second set of wheels</button>'+
    '</div>'+
    '<label class="f-lbl fgap">Wheel size</label>'+
    '<div class="chips" id="'+p+'-dia" data-single="1">'+
      [15,16,17,18,19,20].map(function(d){ return '<button type="button" class="chip" data-v="'+d+'">'+d+' inch</button>'; }).join("")+
    '</div>'+
    '<label class="f-lbl fgap">Does the car have tire pressure sensors?</label>'+
    '<div class="chips" id="'+p+'-tp" data-single="1">'+
      '<button type="button" class="chip" data-v="yes">Yes<small>A light comes on when a tire is low</small></button>'+
      '<button type="button" class="chip" data-v="no">No<small>Plenty of Canadian cars never had them</small></button>'+
      '<button type="button" class="chip" data-v="light">Yes, but I will run with the light on<small>Legal in Canada, just a nuisance</small></button>'+
      '<button type="button" class="chip" data-v="idk">Not sure</button>'+
    '</div>'+
    '<div class="f-hint">Canada never required tire pressure sensors, so many cars here do not have them at any age. If yours does, a second set of wheels needs its own sensors to keep the dash light off.</div>'+
    '<label class="f-lbl fgap">Who does the seasonal change?</label>'+
    '<div class="chips" id="'+p+'-diy" data-single="1">'+
      '<button type="button" class="chip" data-v="shop">A shop does it</button>'+
      '<button type="button" class="chip" data-v="diy">I do it myself in the driveway</button>'+
    '</div>'+
    '<label class="f-lbl fgap">How many more winters with this car?</label>'+
    '<div class="chips" id="'+p+'-yrs" data-single="1">'+
      '<button type="button" class="chip" data-v="1">One</button>'+
      '<button type="button" class="chip" data-v="3">Two or three</button>'+
      '<button type="button" class="chip" data-v="5">Four or five</button>'+
      '<button type="button" class="chip" data-v="7">Six or more</button>'+
    '</div>'+
    '<div class="fgap"><button type="button" class="btn btn-primary" id="'+p+'-run">Work it out</button></div>'+
    '<div id="'+p+'-out"></div>';
  },
  compute: function(p){
    var wh=chipVal(p+"-wh"), dia=+chipVal(p+"-dia"), tp=chipVal(p+"-tp"), diy=chipVal(p+"-diy"), yrs=+chipVal(p+"-yrs");
    if(!wh||!dia||!tp||!diy||!yrs) return {missing:true};
    if(wh==="have") return {own:true};

    var W = CFG.wheels;
    var winterRim = Math.min(dia, 17);
    var wheelCost = winterRim<=16 ? W.steel16 : W.steel17;
    var downNote = dia>winterRim
      ? "We sized the winter set down to "+winterRim+" inch steel, the standard move for a "+dia+" inch car. Cheaper wheels, cheaper tires, more sidewall against winter potholes, and it clears the brakes on almost all cars that came on "+dia+"s. We confirm the fit before ordering."
      : "";

    var tpmsCost = 0, tpmsNote = "";
    if(tp==="yes" || tp==="idk"){ tpmsCost = CFG.tpms.aftermarket*4; tpmsNote = "Four programmable sensors at about "+money(CFG.tpms.aftermarket)+" each, against roughly "+money(CFG.tpms.oem)+" at the dealer. On a second set of wheels this is a one-time cost."; }
    else if(tp==="light"){ tpmsCost = 0; tpmsNote = "No sensors fitted, so the dash light stays on all winter. That is legal in Canada and costs nothing, but you give up the low-pressure warning in the season you most want it."; }
    else { tpmsNote = "No sensors on the car, so there is nothing to buy for the second set."; }

    var upfront = wheelCost + tpmsCost;
    var perChange = CFG.service.mountBalance;
    var perSwap = CFG.service.swapOnRims;
    var v = CFG.service.visitsPerYear;
    var annualOne = perChange * v;
    var annualTwo = (diy==="diy") ? 0 : perSwap * v;
    var saving = annualOne - annualTwo;
    var alloyValue = (wh==="alloy" || wh==="after") ? CFG.alloyRisk : 0;
    var totalPerYear = saving + alloyValue;
    var resale = Math.round(wheelCost * CFG.wheels.resale);
    var breakeven = totalPerYear>0 ? ((upfront - resale) / totalPerYear) : 99;
    var net = totalPerYear*yrs + resale - upfront;

    var rec = net > 120 ? "two" : (net > -120 ? "close" : "one");
    return {wh:wh,dia:dia,winterRim:winterRim,downNote:downNote,tp:tp,diy:diy,yrs:yrs,
      wheelCost:wheelCost,tpmsCost:tpmsCost,tpmsNote:tpmsNote,upfront:upfront,
      annualOne:annualOne,annualTwo:annualTwo,saving:saving,alloyValue:alloyValue,
      resale:resale,breakeven:breakeven,net:net,rec:rec};
  },
  resultHTML: function(r){
    if(r.missing) return '<div class="warnnote">A couple of answers still missing.</div>';
    if(r.own) return '<div class="result"><div class="rbig">You are already set</div><div>You own the second set, so the only thing left is the swap itself, roughly '+money(CFG.service.swapOnRims*CFG.service.visitsPerYear)+' a year at a shop. That goes into the cohort auction with everything else.</div></div>';

    var head = r.rec==="two" ? "Two sets of wheels" : (r.rec==="one" ? "One set of wheels" : "Close, so let convenience decide");
    var h = '<div class="result'+(r.rec==="close"?" alt":"")+'"><div class="rbig">'+head+'</div>';

    if(r.rec==="two"){
      h += '<div>The money is only part of this, and usually the smaller part. A second set means your winter tires are mounted once and simply bolted on each season, a fifteen minute swap instead of an hour-long changeover booked into the November rush, and your good wheels stay out of the salt. Over '+r.yrs+' more winter'+(r.yrs>1?'s':'')+' the arithmetic also lands about <b>'+money(Math.abs(r.net))+' ahead</b>.</div>';
    } else if(r.rec==="one"){
      h += '<div>A second set is not worth it here. Keep the one set, pay for the changeover twice a year, and put the difference toward better tires. The money comes out about <b>'+money(Math.abs(r.net))+' behind</b> over '+r.yrs+' winter'+(r.yrs>1?'s':'')+', and the convenience does not close that gap for you.</div>';
    } else {
      h += '<div>On money this is a wash, within about '+money(Math.abs(r.net))+' either way over '+r.yrs+' winter'+(r.yrs>1?'s':'')+', so let the other side decide. A second set buys a fifteen minute swap and stops your tires being pried off the rim twice a year. If that is worth a few hundred dollars up front to you, take it.</div>';
    }

    if(r.downNote) h += '<div class="because"><b>On wheels:</b> '+r.downNote+'</div>';

    h += '<div class="because"><b>The break-even is '+(r.breakeven>=90?"never at these numbers":r.breakeven.toFixed(1)+" winters")+'.</b> ';
    h += (r.diy==="diy") ? 'Doing the swap yourself is what moves it, because you skip the bill entirely rather than trading a big one for a small one.' : 'A changeover breaks the tire off the rim and rebalances it, about '+money(CFG.service.mountBalance)+' a visit. A wheel swap is about '+money(CFG.service.swapOnRims)+'.';
    h += '</div>';

    h += '<div class="mathbox"><button type="button">Show the arithmetic</button><div><table>'+
      '<tr><td>Second set of '+r.winterRim+' inch steel wheels'+(r.dia>r.winterRim?' (sized down from '+r.dia+')':'')+'</td><td>'+money(r.wheelCost)+'</td></tr>'+
      '<tr><td>Pressure sensors</td><td>'+(r.tpmsCost?money(r.tpmsCost):"none")+'</td></tr>'+
      '<tr><td><b>Up front</b></td><td><b>'+money(r.upfront)+'</b></td></tr>'+
      '<tr><td>Changeover each year with one set</td><td>'+money(r.annualOne)+'</td></tr>'+
      '<tr><td>Swap each year with two sets'+(r.diy==="diy"?" (you do it)":"")+'</td><td>'+money(r.annualTwo)+'</td></tr>'+
      '<tr><td>Saved each year</td><td>'+money(r.saving)+'</td></tr>'+
      (r.alloyValue?'<tr><td>Not putting your alloys through road salt</td><td>'+money(r.alloyValue)+' a year</td></tr>':'')+
      '<tr><td>Wheels are worth something when you sell</td><td>'+money(r.resale)+'</td></tr>'+
      '<tr><td><b>Over '+r.yrs+' winter'+(r.yrs>1?'s':'')+'</b></td><td><b>'+(r.net>=0?"+":"")+money(r.net)+'</b></td></tr>'+
      '</table><div style="margin-top:9px">GTA retail, 2026. Your cohort price should come in under these.</div></div></div>';

    if(r.tpmsNote) h += '<div class="cave">'+r.tpmsNote+'</div>';
    if(r.wh==="alloy" || r.wh==="after"){
      h += '<div class="cave">The argument nobody puts on a quote: five winters of road salt on factory alloys costs real money to put right, somewhere around '+money(150)+' to '+money(250)+' a wheel to refinish. Steel is what winter is supposed to eat.</div>';
    }
    if(S.tools.size && S.tools.size.staggered){
      h += '<div class="cave">Your car is staggered, so a second set means a square winter setup on dedicated wheels, which we size by hand.</div>';
    }
    h += '</div>';
    return h;
  },
  bind: function(p){
    var self=this;
    ["-wh","-dia","-tp","-diy","-yrs"].forEach(function(sfx){ bindChips($(p+sfx)); });
    var t = S.tools.size;
    if(t && t.chosen){ var sz = parseSize(t.chosen); if(sz) setChip(p+"-dia", String(sz.r)); }
    $(p+"-wh").addEventListener("chipchange", function(){
      var own = chipVal(p+"-wh")==="have";
      ["-dia","-tp","-diy","-yrs"].forEach(function(sfx){
        qsa(".chip", $(p+sfx)).forEach(function(c){ if(own){ c.dataset.off="1"; } else { delete c.dataset.off; } });
      });
    });
    $(p+"-run").addEventListener("click", function(){
      var r = self.compute(p);
      $(p+"-out").innerHTML = self.resultHTML(r);
      var mb = qs(".mathbox", $(p+"-out"));
      if(mb) mb.querySelector("button").addEventListener("click", function(){ mb.classList.toggle("open"); });
      if(!r.missing) saveTool("rims", r);
    });
  },
  verdict: function(t){
    if(t.own) return "Already have a second set";
    if(t.rec==="two") return "Two sets, about "+money(Math.abs(t.net))+" ahead";
    if(t.rec==="one") return "One set is cheaper here";
    return "Close, your call on convenience";
  }
};
TOOLS.ins = {
  html: function(p){
    var provOpts = [["ON","Ontario"],["QC","Quebec"],["BC","British Columbia"],["AB","Alberta"],["OTHER","Somewhere else"]]
      .map(function(o){ return '<option value="'+o[0]+'">'+o[1]+'</option>'; }).join("");
    return ''+
    '<div class="frow">'+
      '<div><label class="f-lbl" for="'+p+'-prov">Province</label><select class="f-in" id="'+p+'-prov">'+provOpts+'</select></div>'+
      '<div><label class="f-lbl" for="'+p+'-prem">What you pay a year for auto insurance</label><input class="f-in" id="'+p+'-prem" type="text" inputmode="numeric" placeholder="1,800"></div>'+
    '</div>'+
    '<label class="f-lbl fgap">Do you know your insurer\'s winter tire discount?</label>'+
    '<div class="chips" id="'+p+'-known" data-single="1">'+
      '<button type="button" class="chip" data-v="no" aria-pressed="true">No, show me the usual range</button>'+
      '<button type="button" class="chip" data-v="yes">Yes, I know the number</button>'+
    '</div>'+
    '<div class="hide fgap" id="'+p+'-rateWrap"><label class="f-lbl" for="'+p+'-rate">Your discount, in percent</label><input class="f-in" id="'+p+'-rate" type="text" inputmode="decimal" placeholder="5" style="max-width:160px"></div>'+
    '<label class="f-lbl fgap">Roughly what you expect to pay per tire</label>'+
    '<div class="chips" id="'+p+'-cost" data-single="1">'+
      '<button type="button" class="chip" data-v="110">About $110</button>'+
      '<button type="button" class="chip" data-v="160">About $160</button>'+
      '<button type="button" class="chip" data-v="220">About $220</button>'+
      '<button type="button" class="chip" data-v="290">About $290</button>'+
    '</div>'+
    '<div class="fgap"><button type="button" class="btn btn-primary" id="'+p+'-run">What is it worth</button></div>'+
    '<div id="'+p+'-out"></div>';
  },
  compute: function(p){
    var prov = $(p+"-prov").value;
    var prem = parseFloat(String($(p+"-prem").value).replace(/[^0-9.]/g,""));
    if(!prem || prem<200 || prem>20000) return {badPrem:true};
    var known = chipVal(p+"-known")==="yes";
    var rate = known ? parseFloat(String($(p+"-rate").value).replace(/[^0-9.]/g,""))/100 : null;
    if(known && (!rate || rate<=0 || rate>0.2)) return {badRate:true};
    var perTire = +chipVal(p+"-cost") || null;

    var lo = known ? rate : CFG.ins.lo, hi = known ? rate : CFG.ins.hi, mid = known ? rate : CFG.ins.likely;
    var life = CFG.ins.tireLife;
    var r = {
      prov:prov, prem:prem, known:known,
      annualLo:Math.round(prem*lo), annualMid:Math.round(prem*mid), annualHi:Math.round(prem*hi),
      lifeLo:Math.round(prem*lo*life), lifeMid:Math.round(prem*mid*life), lifeHi:Math.round(prem*hi*life),
      perTire:perTire, life:life, setCost:perTire?perTire*4:null,
      mandated:(CFG.ins.provinces[prov]||CFG.ins.provinces.OTHER).mandated,
      note:(CFG.ins.provinces[prov]||CFG.ins.provinces.OTHER).note
    };
    if(r.setCost){ r.netSet = r.setCost - r.lifeMid; r.pct = Math.round(r.lifeMid/r.setCost*100); }
    return r;
  },
  resultHTML: function(r, strategy){
    if(r.badPrem) return '<div class="warnnote">Put in your annual auto premium, somewhere between a few hundred and a few thousand dollars.</div>';
    if(r.badRate) return '<div class="warnnote">A winter tire discount is normally between 1 and 10 percent.</div>';
    var band = r.known ? money(r.annualMid)+" a year" : money(r.annualLo)+" to "+money(r.annualHi)+" a year";
    var h = '<div class="result"><div class="rbig">'+band+'</div>';
    h += '<div>Over the five or six winters a set of tires normally lasts, that is '+(r.known?money(r.lifeMid):money(r.lifeLo)+" to "+money(r.lifeHi))+'.</div>';
    if(r.setCost){
      h += '<div class="because">A set at about '+money(r.perTire)+' a tire runs '+money(r.setCost)+'. Taking the middle of the range, the discount covers roughly <b>'+r.pct+' percent</b> of that, leaving about '+money(r.netSet)+' out of pocket over '+r.life+' winters.</div>';
    }
    h += '<div class="because"><b>Because it is a percentage, the higher your premium the more this matters.</b> A newer driver in a high-rate postal code can get several times what a retiree with a clean record gets, so this is worth far more to some drivers than others.</div>';
    h += '<div class="because"><b>The part nobody counts:</b> five or six months a year on winter tires is five or six months your all-seasons are not wearing out, so that set typically lasts an extra season and a half. Real money you never see as a line item.</div>';
    h += '<div class="cave"><b>It is not automatic.</b> You have to tell your insurer and see the discount on your policy documents, not just mention it, and keep the receipt or a photo of the tires on the car. Most people who miss out never declared it, or installed outside their insurer\'s window.</div>';
    h += '<div class="cave"><b>'+r.note+'</b> The size of the discount is set by each insurer, so treat the range above as a guide until your broker confirms your number.</div>';
    h += '<div class="cave"><b>What insurers normally want:</b> four matching winter tires carrying the mountain snowflake, not two, installed and kept on through their window, usually about November 1 to April 1 or 15. Most do not care how old the tires are, though a few set an age limit, and some ask for the receipt.</div>';
    if(strategy==="allweather"){
      h += '<div class="warnnote">You have chosen all-weather tires. Most Ontario insurers will not give this discount for all-weather, even with the mountain snowflake, because it is not a dedicated second set. On your premium that decision is worth about '+band+', worth weighing against the storage and changeover you are avoiding.</div>';
    }
    h += '<div class="because" style="font-size:13px">This is a general estimate, not insurance advice, and Whollar is not an insurance broker. Your insurer sets your rate.</div>';
    h += '</div>';
    return h;
  },
  bind: function(p){
    var self=this;
    bindChips($(p+"-known")); bindChips($(p+"-cost"));
    if(S.city && CITY_PROV[S.city]) $(p+"-prov").value = CITY_PROV[S.city];
    $(p+"-known").addEventListener("chipchange", function(){ show($(p+"-rateWrap"), chipVal(p+"-known")==="yes"); });
    $(p+"-run").addEventListener("click", function(){
      var r = self.compute(p);
      var strat = S.tools.strat ? S.tools.strat.choice : null;
      $(p+"-out").innerHTML = self.resultHTML(r, strat);
      if(!r.badPrem && !r.badRate) saveTool("ins", r);
    });
  },
  verdict: function(t){
    if(t.known) return money(t.annualMid)+" a year back";
    return money(t.annualLo)+" to "+money(t.annualHi)+" a year back";
  }
};
var MOUNTS = {
  strat: [["wm-mount-strat","kxstrat"],["mount-g-strat","gxstrat"]],
  size:  [["wm-mount-size","kxsize"],  ["mount-g-size","gxsize"]],
  rims:  [["wm-mount-rims","kxrims"],  ["mount-g-rims","gxrims"]],
  ins:   [["wm-mount-ins","kxins"],    ["mount-g-ins","gxins"]]
};
function mountTool(name, hostId, prefix){
  var host = $(hostId); if(!host) return;
  host.innerHTML = TOOLS[name].html(prefix);
  host.dataset.mounted = prefix;
  TOOLS[name].bind(prefix);
}
function remountOther(name, notPrefix){
  MOUNTS[name].forEach(function(m){
    var host=$(m[0]);
    if(host && host.dataset.mounted && host.dataset.mounted !== notPrefix){ mountTool(name, m[0], m[1]); }
  });
}
function saveTool(name, data){
  S.tools[name] = data;
  syncVerdicts();
  applyPrefill(name, data);
  updateMeter();
}


/* ============================================================
   VERDICTS, GATING AND PREFILL
   ============================================================ */
function syncVerdicts(){
  var done = 0;
  ["strat","size","rims","ins"].forEach(function(k){
    var t = S.tools[k], card = $("tool-"+k), v = $("verdict-"+k);
    var text = t ? TOOLS[k].verdict(t) : "";
    if(v) v.textContent = text;
    if(card) card.classList.toggle("done", !!text);
    if(text) done++;
    var saved = $("saved-g-"+k);
    if(saved) saved.innerHTML = text ? '<span class="savedchip">'+esc(text)+'</span>' : "";
  });
  var t = $("tally"); if(t) t.textContent = done + " of 4 answered";

  // carry-over chips at signup
  var box = $("kitchips");
  if(box){
    var bits = [];
    if(S.tools.strat) bits.push(TOOLS.strat.verdict(S.tools.strat));
    if(S.tools.size)  bits.push(TOOLS.size.verdict(S.tools.size));
    if(S.tools.rims)  bits.push(TOOLS.rims.verdict(S.tools.rims));
    if(S.tools.ins)   bits.push(TOOLS.ins.verdict(S.tools.ins));
    box.innerHTML = bits.length ? '<span class="kc" style="background:transparent;border:0;color:var(--sub);padding-left:0">Carried over from your answers above:</span>' + bits.map(function(b){ return '<span class="kc">'+esc(b)+'</span>'; }).join("") : "";
    box.classList.toggle("hide", !bits.length);
  }
}

/* strategy drives what the rest of the form is even allowed to say */
function applyStrategy(v){
  var aw = (v==="allweather");
  qsa(".winter-only").forEach(function(el){ el.classList.toggle("hide", aw); });
  show($("awCaveat"), aw);
  var rimsCard = $("tool-rims");
  if(rimsCard){
    rimsCard.classList.toggle("locked", aw);
    if(aw){ rimsCard.classList.remove("open"); }
  }
  gateNeeds();
  fillLines();
}

/* what you need has to agree with where you are starting from */
function gateNeeds(){
  var have = chipVal("g_have");
  var strat = chipVal("g_strategy");
  var worn = chipVal("g_worn");
  var off = {}, reasons = [];

  if(strat==="allweather"){
    off.wheels = "All-weather tires stay on all year, so there is no second set of wheels.";
    off.swap   = "Nothing to swap. One set of tires lives on the car.";
    off.storage= "Nothing to store.";
    off.tpms   = "Sensors are only a second-set problem.";
    reasons.push("all-weather means one set of tires on the car all year, so the wheels, swap and storage options are off");
  }
  if(have==="tireswheels"){
    off.tires = "You told us you already have winter tires.";
    off.wheels = "And they are already on their own wheels.";
    off.tpms = "Those wheels already have whatever sensors they are going to have.";
    reasons.push("you already have winter tires on wheels, so the only things left are fitting them and storing the others");
  }
  if(have==="tires" && worn!=="done"){
    off.tires = "You told us your winter tires still have life in them.";
    reasons.push("your winter tires still have life, so tires come off the list until they do not");
  }
  if(have==="allweather"){
    off.wheels = "All-weather tires stay on all year.";
    off.swap = "Nothing to swap.";
    off.storage = "Nothing to store.";
    off.tpms = "Sensors are only a second-set problem.";
  }
  // sensors only make sense alongside a second set of wheels
  var needs = chipVals("g_needs");
  if(!off.tpms && needs.indexOf("wheels")===-1 && !(S.tools.rims && S.tools.rims.rec==="two")){
    off.tpms = "Pick a second set of wheels first. Sensors go in the second set.";
  }
  gateChips("g_needs", off, "needsGate", reasons.length ? "Some options are switched off because "+reasons.join(", and ")+"." : "");

  // strategy itself can be forced by what they already own
  var soff = {};
  if(have==="allweather"){ soff.winter = "You told us all-weather tires are already on the car."; setChip("g_strategy","allweather"); }
  if(have==="tires" || have==="tireswheels"){ soff.allweather = "You already own winter tires, so switching to all-weather would mean throwing them away."; setChip("g_strategy","winter"); }
  gateChips("g_strategy", soff, "strategyGate",
    have==="allweather" ? "Locked to all-weather because that is what is on the car. Change the answer above if that is wrong." :
    ((have==="tires"||have==="tireswheels") ? "Locked to winter tires because you already own a set. Change the answer above if that is wrong." : ""));
}

function applyPrefill(name, d){
  if(name==="strat" && d.choice){
    setChip("g_strategy", d.choice); setChip("q_strategy", d.choice); applyStrategy(d.choice);
  }
  if(name==="size" && d.oe){
    setChip("g_mode","size"); modeShow("g"); var gs=$("g_size"); if(gs) gs.value = d.oe;
    setChip("q_mode","size"); modeShow("q"); var qsz=$("q_size"); if(qsz) qsz.value = d.oe;
    if(d.vehicle){
      var bits = d.vehicle.split(" ");
      var y = bits.shift();
      if($("g_year")) $("g_year").value = y;
    }
    updateSizeAck("g"); updateSizeAck("q");
  }
  if(name==="rims"){
    if(d.rec==="two"){ var b = qs('#g_needs .chip[data-v="wheels"]'); if(b && b.dataset.off!=="1") b.setAttribute("aria-pressed","true"); }
    gateNeeds();
  }
  if(name==="ins"){ var c=$("g_insHelp"); if(c) c.checked = true; }
}

function modeShow(pfx){
  var v = chipVal(pfx+"_mode");
  show($(pfx+"_sizeWrap"), v==="size");
  show($(pfx+"_vehWrap"), v==="vehicle");
  updateSizeAck(pfx);
}

/* The size acknowledgement only appears once a size is actually on the table,
   and is required only while it is visible. If they have no size yet, there is
   nothing to confirm, so it does not block. */
function sizeKnown(pfx){
  var v = chipVal(pfx+"_mode");
  if(v==="size") return !!parseSize($(pfx+"_size").value);
  if(v==="vehicle") return !!($(pfx+"_year").value && $(pfx+"_make").value && $(pfx+"_model").value);
  return false;
}
function updateSizeAck(pfx){
  var wrap = $(pfx+"_sizeAckWrap");
  if(!wrap) return;
  var known = sizeKnown(pfx);
  show(wrap, known);
  if(!known){ var cb=$(pfx+"_sizeAck"); if(cb) cb.checked=false; bad(pfx+"_sizeAck","e_"+pfx+"_sizeAck",false); }
}

/* ============================================================
   BRAND AND LINE SELECTS  (filtered by winter vs all-weather)
   ============================================================ */
function fillBrands(){
  var sel = $("g_brand"); if(!sel) return;
  sel.innerHTML = '<option value="">No preference</option>' + Object.keys(BRANDS).sort().map(function(b){ return '<option>'+esc(b)+'</option>'; }).join("");
}
function fillLines(){
  var bSel=$("g_brand"), lSel=$("g_line"); if(!bSel||!lSel) return;
  var b = bSel.value;
  var strat = chipVal("g_strategy") || (S.tools.strat && S.tools.strat.choice) || "winter";
  if(!b){ lSel.innerHTML='<option value="">Pick a brand first</option>'; lSel.disabled=true;
          $("lineHint").textContent = "Only the lines sold in Canada this season are listed, filtered to match the choice you made above."; return; }
  var want = strat==="allweather" ? ["a"] : ["w","s"];
  var lines = (BRANDS[b]||[]).filter(function(l){ return want.indexOf(l.t)>=0; });
  lSel.disabled = false;
  if(!lines.length){
    lSel.innerHTML = '<option value="">Nothing from '+esc(b)+' in this category</option>';
    $("lineHint").textContent = esc(b)+" does not sell "+(strat==="allweather"?"an all-weather":"a winter")+" line in Canada that we can source. Pick another brand or leave it as no preference.";
    return;
  }
  lSel.innerHTML = '<option value="">No preference within '+esc(b)+'</option>' + lines.map(function(l){
    return '<option value="'+esc(l.n)+'">'+esc(l.n)+(l.t==="s"?" (studdable)":"")+'</option>';
  }).join("");
  $("lineHint").textContent = strat==="allweather"
    ? "Showing only all-weather lines. These carry the mountain snowflake and stay on all year, which is not the same thing as an all-season tire."
    : "Showing only winter lines. Studdable models are marked, and studs are legal in Ontario only from October 1 to April 30 in northern regions, so we will flag it if it applies to you.";
}

/* ============================================================
   BATCHES AND THE LINE
   ============================================================ */
function waveOf(rank){ return Math.max(1, Math.ceil(rank / CFG.waveSize)); }
function waveDate(n){ return CFG.waveDates[Math.min(n-1, CFG.waveDates.length-1)]; }
function renderWaveList(){
  var host = $("waveList"); if(!host) return;
  var next = waveOf(S.counts.gta + 1);
  var rows = [];
  for(var i=1;i<=Math.min(next+1, CFG.waveDates.length);i++){
    var cls = i===1 ? "open" : (i===next ? "next" : "");
    var lbl = i===1 ? "Opens first" : (i===next ? "Where you would land" : "");
    rows.push('<div class="bt '+cls+'"><span class="bdot"></span><b>Wave '+i+'</b><span>'+waveDate(i)+(lbl?" · "+lbl:"")+'</span></div>');
  }
  if(next+1 < CFG.waveDates.length) rows.push('<div class="bt"><span class="bdot"></span><b>and on</b><span>through '+waveDate(CFG.waveDates.length)+'</span></div>');
  host.innerHTML = rows.join("");
}
function updateHeroCounts(){
  var n = S.counts.gta;
  if($("heroCount")) $("heroCount").textContent = nf(n);
  if($("topCount")) $("topCount").textContent = nf(n);
  if($("heroNext")) $("heroNext").textContent = nf(n+1);
  if($("heroWave")) $("heroWave").textContent = "Wave " + waveOf(n+1);
  renderWaveList();
}

/* ============================================================
   PROFILE COMPLETENESS  (the qualification signal)
   ============================================================ */
var METER_ITEMS = [
  {w:20, f:function(){ return $("g_first").value.trim() && $("g_last").value.trim() && RE.email.test($("g_email").value.trim()) && chipVal("g_city"); }},
  {w:8,  f:function(){ return !!chipVal("g_have"); }},
  {w:8,  f:function(){ return !!chipVal("g_strategy"); }},
  {w:14, f:function(){ var m=chipVal("g_mode"); return m==="size" ? !!parseSize($("g_size").value) : (m==="vehicle" ? ($("g_make").value && $("g_model").value && $("g_year").value) : false); }},
  {w:8,  f:function(){ return chipVals("g_needs").length>0; }},
  {w:6,  f:function(){ return !!chipVal("g_tier"); }},
  {w:12, f:function(){ return S.prefs.length>0; }},
  {w:6,  f:function(){ return !!chipVal("g_installer"); }},
  {w:10, f:function(){ return !!chipVal("g_budget"); }},
  {w:8,  f:function(){ return chipVals("g_prior").length>0; }}
];
function updateMeter(){
  if(!$("meter")) return;
  var pct = 0;
  METER_ITEMS.forEach(function(it){ try{ if(it.f()) pct += it.w; }catch(e){} });
  pct = Math.min(100, pct);
  $("meterPct").textContent = pct + "% complete";
  $("meterBar").style.width = pct + "%";
  var base = S.rank || (S.counts.gta + 1);
  var b = waveOf(base);
  $("meterBadge").textContent = "Wave " + b;
  $("meterMsg").textContent = pct >= 85
    ? "This is a profile we can price without emailing you a single question."
    : (pct >= 50 ? "Halfway. The dates and the budget are the two that matter most to a bidder."
                 : "A complete profile is one we can price without chasing you.");
}

/* ============================================================
   THE CALENDAR
   ============================================================ */
function d2s(d){ return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
function s2d(v){ var a=String(v).split("-"); return new Date(+a[0], +a[1]-1, +a[2]); }
var MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
var DOW=["Su","Mo","Tu","We","Th","Fr","Sa"];
function prettyDate(v){ var d=s2d(v); return ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][d.getDay()]+", "+MONTHS[d.getMonth()]+" "+d.getDate(); }
function shortDate(v){ var d=s2d(v); return ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][d.getDay()]+" "+MONTHS[d.getMonth()].slice(0,3)+" "+d.getDate(); }

function buildCal(){
  var fromV=$("g_from").value, toV=$("g_to").value;
  if(!fromV||!toV) return false;
  var from=s2d(fromV), to=s2d(toV);
  if(to < from){ bad("g_to","e_g_range",true); return false; }
  bad("g_to","e_g_range",false);

  var host=$("calmonths"), out=[];
  var cur = new Date(from.getFullYear(), from.getMonth(), 1);
  var guard = 0;
  while(cur <= to && guard++ < 8){
    var y=cur.getFullYear(), m=cur.getMonth();
    var first=new Date(y,m,1), days=new Date(y,m+1,0).getDate();
    var cells = DOW.map(function(d){ return '<div class="caldow">'+d+'</div>'; });
    for(var i=0;i<first.getDay();i++) cells.push('<div class="calday out"></div>');
    for(var d=1; d<=days; d++){
      var dd=new Date(y,m,d), v=d2s(dd);
      var okDay = dd>=from && dd<=to;
      var wknd = (dd.getDay()===0 || dd.getDay()===6);
      var sel = S.prefs.some(function(x){ return x.date===v; });
      cells.push('<button type="button" class="calday'+(wknd?" wknd":"")+(sel?" sel":"")+'" data-d="'+v+'"'+(okDay?"":" disabled")+'>'+d+'</button>');
    }
    out.push('<div class="calmonth"><h4>'+MONTHS[m]+' '+y+'</h4><div class="calgrid">'+cells.join("")+'</div></div>');
    cur = new Date(y, m+1, 1);
  }
  host.innerHTML = out.join("");
  return true;
}
function renderPrefs(){
  var host=$("prefs");
  host.innerHTML = S.prefs.map(function(x,i){
    return '<div class="pref"><span class="pn">'+(i+1)+'</span><span><b>'+shortDate(x.date)+'</b> · '+SLOTS[x.slot]+'</span><button type="button" class="px" data-rm="'+i+'">Remove</button></div>';
  }).join("");
  var left = CFG.maxPrefs - S.prefs.length;
  $("prefCount").textContent = S.prefs.length===0
    ? "Pick up to five. Your first choice is the one we chase hardest."
    : (left>0 ? S.prefs.length+" picked, "+left+" more you can add. They are ranked in the order you pick them."
              : "That is all five. Remove one if you want to swap it out.");
  updateMeter();
}

/* ============================================================
   CAPTURE, REFERENCE, CONFIRMATION
   ============================================================ */
var CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
function makeRef(cityV){
  var c = CITIES.filter(function(x){ return x.v===cityV; })[0] || CITIES[6];
  var tail=""; for(var i=0;i<4;i++) tail += CHARS[Math.floor(Math.random()*CHARS.length)];
  return "WHL-TIRE-"+c.code+"-"+tail;
}
function capture(cityV){
  if(S.captured) return;
  S.captured = true;
  S.city = cityV;
  S.counts[cityV] = (S.counts[cityV]||0) + 1;
  S.rank = S.counts[cityV];
  S.wave = waveOf(S.rank);
  updateHeroCounts();
  renderCities();
}
function renderCities(){
  var g=$("citygrid"); if(!g) return;
  g.innerHTML = CITIES.map(function(c){
    var n = S.counts[c.v];
    var pct = c.conf ? 100 : Math.min(100, Math.round(n/CFG.cityThreshold*100));
    var togo = c.conf ? "Confirmed. Bidding opens in early October." : (CFG.cityThreshold-n)+" more households and this one goes to auction.";
    return '<div class="city'+(c.conf?" conf":"")+'"><div class="nm"><b>'+esc(c.n)+'</b><span>'+(c.conf?"Confirmed":nf(n)+" of "+nf(CFG.cityThreshold))+'</span></div>'+
      '<div class="bar"><i data-w="'+pct+'"></i></div><div class="togo">'+togo+'</div></div>';
  }).join("");
  var bars = qsa("#citygrid .bar i");
  if(!("IntersectionObserver" in window)){ bars.forEach(function(b){ b.style.width=b.getAttribute("data-w")+"%"; }); return; }
  var io=new IntersectionObserver(function(es){ es.forEach(function(e){ if(e.isIntersecting){ e.target.style.width=e.target.getAttribute("data-w")+"%"; io.unobserve(e.target); } }); },{threshold:.3});
  bars.forEach(function(b){ io.observe(b); });
}

function renderQueue(){
  if(!$("qYou")) return;   /* the referral panel is not on this page */
  var total = Math.max(S.wave, waveOf(S.counts[S.city]||1), 2);
  var pos = 1 - ((S.wave-1) / Math.max(1,total-1));
  var pctLeft = Math.max(4, Math.min(96, ( (total - S.wave) / Math.max(1,total-1) ) * 100));
  $("qYou").style.left = pctLeft + "%";
  $("qFill").style.width = pctLeft + "%";
  $("qPin").textContent = "B"+S.wave;
  $("qEnd").textContent = "Wave " + total;
  $("rsJoined").textContent = S.refJoined;
  $("rsMoved").textContent = S.refMoved;
  $("rsInvites").textContent = S.invitesLeft;
  $("inviteRow").innerHTML = (function(){
    var out=[];
    for(var i=0;i<CFG.inviteCount;i++){
      var used = i < (CFG.inviteCount - S.invitesLeft);
      out.push('<div class="inv'+(used?" used":"")+'">'+(used?"Invite used":"Invite "+(i+1))+'</div>');
    }
    return out.join("");
  })();
  $("lineCopy").innerHTML = CFG.referralMode==="skip"
    ? 'Every friend who joins on your link moves you up <b>'+CFG.referralJump+' places</b>, to a maximum of '+CFG.referralCap+'. You also get '+CFG.inviteCount+' invites that drop someone straight into your wave instead of the back of the line.'
    : 'Referrals do not move you past anyone, because your place is fixed at the moment you joined. What they do is get the cohort to its number sooner, which pulls the auction date forward for everybody including you.';
}


var TIRE_API = "https://whollar-110003037934.development.catalystserverless.ca/server/formSubmit";

/* Mirrors W.submitForm in js/whollar-core.js. See the note in
   scripts/port-tires.mjs section 10e1 before changing the Content-Type. */
function postForm(path, fields){
  return fetch(TIRE_API + path, { method: "POST", body: JSON.stringify(fields) })
    .then(function(r){
      return r.json().catch(function(){ return null; }).then(function(body){
        if(!r.ok){
          var e = new Error((body && body.error) || ("submit failed: " + r.status));
          e.status = r.status; e.body = body;
          throw e;
        }
        return body || {};
      });
    });
}

/* Mirrors W.consentPayload. The field names are read by consentFrom() in
   catalyst-backend/functions/formSubmit/index.js, so the two are only correct
   while they agree. CASL needs what was agreed, when, and where. */
var CONSENT_TEXT = "Add me to the Whollar winter tire cohort and email me about it. I understand this is not a purchase and nothing is charged today.";

/* What the route expects. Built from the same S.record the page already
   assembles, so the form stays the source of truth and this is only a shape. */
function submitPayload(){
  var r = S.record, t = S.tools || {};
  var veh = {
    inputMode: r.veh_entry_mode || "unsure",
    year: r.veh_year, make: r.veh_make, model: r.veh_model,
    vin: r.vin, tireSize: r.tire_size,
    sizeNormalized: (t.size && t.size.oe) || null,
    strategy: r.strategy,
    startingPoint: r.have,
    tireLifeLeft: r.tire_life_left,
    trim: r.veh_trim,
    winterSizeChosen: r.winter_size_chosen,
    sizeDownsized: r.size_downsized,
    sizeAck: r.size_ack,
    staggered: r.staggered,
    tpmsPresent: r.tpms_present,
    rimsRecommendation: r.rims_recommendation,
    ownsRims: (t.rims && t.rims.wh) || null,
    runsWinterNow: null
  };
  var details = r.path === "guided" ? {
    needs: (r.needs || []).join(","),
    tier: r.tier, brand: r.brand, budget: r.budget_per_tire,
    financing: r.financing_interest, installerType: r.installer_type,
    splitPreference: r.split_install_storage ? "prefer" : null,
    installWindows: (r.preferred_slots || []).map(function(x){ return x.date + " " + x.slot; }).join(", "),
    notBefore: r.window_earliest, mustBeOnBy: r.window_latest,
    memberships: (r.memberships || []).join(","),
    priorities: (r.priorities || []).join(","),
    readiness: r.readiness, notes: r.notes,
    brandLine: r.brand_line, travelRadius: r.travel_radius,
    installerName: r.installer_name, installerAddress: r.installer_address,
    installerPostal: r.installer_postal,
    insuranceHelp: r.insurance_help, insurerProvince: r.insurer_province,
    premiumAnnual: r.premium_annual,
    /* Everything asked that has no column, kept verbatim so a new question is
       not a schema change. */
    payload: { language: r.language, smsOpt: r.sms_opt, staggered: r.staggered,
      vehTrim: r.veh_trim, toolsAnswered: Object.keys(t) }
  } : null;

  return {
    path: r.path, source: "tires-site",
    firstName: r.first_name, lastName: r.last_name, email: r.email,
    phone: r.mobile, postalFull: r.postal, city: r.city,
    language: r.language || "en", referral: null,
    consentEmail: !!r.consent_cohort,
    consentSms: !!r.sms_opt,
    consentShare: !!r.consent_share_installers,
    alsoInternet: !!r.consent_internet,
    consentGranted: !!r.consent_cohort,
    consentKind: "tire-cohort",
    consentText: CONSENT_TEXT,
    consentAt: new Date().toISOString(),
    consentSource: window.location.pathname,
    vehicles: [veh],
    details: details,
    windows: (r.preferred_slots || []).map(function(x){ return { date: x.date, slot: x.slot, rank: x.rank }; }),
    toolRuns: Object.keys(t).map(function(k){ return { tool: k, input: null, output: t[k] }; })
  };
}

function busyFinish(on){
  var b = qs("#g3 button[type=submit]") || qs("#quickForm button[type=submit]");
  if(!b) return;
  b.disabled = on;
  b.style.opacity = on ? "0.6" : "";
  b.dataset.label = b.dataset.label || b.textContent;
  b.textContent = on ? "Saving your spot..." : b.dataset.label;
}

function finish(){
  busyFinish(true);
  S.ref = makeRef(S.city);
  var r = S.record;
  r.ref_code = S.ref; r.rank = S.rank; r.wave = S.wave; r.city = S.city;
  r.tools = S.tools; r.preferred_slots = S.prefs.map(function(x,i){ return {date:x.date, slot:x.slot, rank:i+1}; });
  r.joined_at = new Date().toISOString();

  postForm("/tire-waitlist-join", submitPayload()).then(function(saved){
    /* The reference is the server's. v5 minted one in the browser, which meant
       two people could hold the same code and nothing could be looked up by
       it. makeRef stays only as the label until this returns. */
    S.ref = saved.reference || S.ref;
    S.wave = saved.wave || S.wave;
    showConfirmation();
  }).catch(function(err){
    busyFinish(false);
    toast(esc(err.message || "We could not save that just now. Nothing was lost, try again."));
  });
  return;
}

/* Split out so the post above has something to call, and so the completion
   screen is built from what came back rather than from what was hoped. */
function showConfirmation(){
  /* Re-enabled on the way through, not only on failure. v5 offers "Add
     another vehicle" from the completion screen, which returns to a form whose
     submit button would otherwise still be disabled and still saying it was
     saving. */
  busyFinish(false);
  var r = S.record;

  var c = CITIES.filter(function(x){ return x.v===S.city; })[0] || CITIES[6];
  if($("confRef")) $("confRef").textContent = S.ref;
  if($("refUrl")) $("refUrl").value = "whollar.ca/tires?r=" + S.ref.split("-").pop();
  if(c.conf){
    $("confTitle").textContent = "You are in.";
    $("confRank").textContent = "Your spot is counted, and we will confirm it by email.";
  } else {
    var togo = Math.max(0, CFG.cityThreshold - S.counts[S.city]);
    $("confTitle").textContent = "Your vote is counted.";
    $("confRank").textContent = "Your vote is counted. We follow the demand.";
  }
  
  
  renderQueue();
  WM.open("You are in", null, function(body){ body.appendChild($("confirmView")); show($("confirmView"), true); });
}


